package edu.gcu.cst339.lab2_chinook_api.invoiceline;

import java.math.BigDecimal;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * Data transfer object used as the JSON request and response body for invoice lines.
 *
 * <p>The validation annotations are checked when a request body is marked
 * {@code @Valid} in the controller.</p>
 *
 * @param invoiceLineId the invoice line ID; generated by the database, so it is
 *                      ignored on create and taken from the URL on update
 * @param invoiceId     ID of the invoice this line belongs to; required and must
 *                      reference an existing invoice
 * @param trackId       ID of the purchased track; required and must reference an
 *                      existing track
 * @param unitPrice     price of one unit; required, zero or more, at most 8 digits
 *                      before the decimal point and 2 after
 * @param quantity      number of units purchased; required and greater than zero
 */
public record InvoiceLineDto(
    Integer invoiceLineId,
    @NotNull
    Integer invoiceId,
    @NotNull
    Integer trackId,
    @NotNull
    @DecimalMin("0.00")
    @Digits(integer = 8, fraction = 2)
    BigDecimal unitPrice,
    @NotNull
    @Positive
    Integer quantity) {
    /**
     * Converts an invoice line entity into a DTO.
     *
     * @param invoiceLine the entity to convert
     * @return a DTO containing all of the entity's fields
     */
    static InvoiceLineDto fromEntity(InvoiceLine invoiceLine) {
        return new InvoiceLineDto(
            invoiceLine.getInvoiceLineId(),
            invoiceLine.getInvoiceId(),
            invoiceLine.getTrackId(),
            invoiceLine.getUnitPrice(),
            invoiceLine.getQuantity()
        );
    }
}
